`timescale 1ns/1ps
// Full-field 128-pixel bilinear lattice, Q8 RGB gains. Seven clock stages.
// Timing and the uncorrected observation tap use the identical seven stages.
module spatial_color #(parameter integer ENABLE=1)(
 input clk,rst_n,input [23:0] rgb_in,input [4:0] timing_in,
 output wire [23:0] rgb_out,input_aligned,output wire [4:0] timing_out
);
// Q8 RGB spatial gains. Generated by fit_nine_point_color.py.
function [29:0] spatial_node;
 input [6:0] address;
 begin case(address)
 7'd0: spatial_node={10'd476,10'd558,10'd500};
 7'd1: spatial_node={10'd422,10'd502,10'd454};
 7'd2: spatial_node={10'd406,10'd467,10'd424};
 7'd3: spatial_node={10'd404,10'd450,10'd410};
