 reg [11:0] col,row;
 wire [11:0] x=timing_in[1]?12'd0:col,y=timing_in[1]?12'd0:row;
 wire [3:0] gx=x>=1280 ? 4'd9 : x[10:7];
 wire [2:0] gy=y>=768 ? 3'd5 : y[9:7];
 wire [6:0] addr={gy,3'b0}+{2'b0,gy,1'b0}+gy+gx;
 wire [29:0] n00=spatial_node(addr),n10=spatial_node(addr+7'd1);
 wire [29:0] n01=spatial_node(addr+7'd11),n11=spatial_node(addr+7'd12);
 reg [23:0] rq[0:6];reg [4:0] tq[0:6];
 reg [6:0] fx1,fy1,fy2,fy3,fy4;
 reg [9:0] base0[0:2],base1[0:2],base02[0:2],base12[0:2];
 reg signed [10:0] delta0[0:2],delta1[0:2];
 reg signed [18:0] product0[0:2],product1[0:2],horizontal0[0:2],horizontal1[0:2],hbase4[0:2];
 reg signed [26:0] vertical4[0:2];
 reg [9:0] gain5[0:2];
 reg [17:0] rgb_product[0:2];
 reg [23:0] corrected;
 function [7:0] clip;
 input [17:0] v;reg [18:0] rounded;
 begin rounded={1'b0,v}+19'd128;clip=rounded>=19'd65536 ? 8'd255 : rounded[15:8];end
 endfunction
 integer k,c;
 always @(posedge clk or negedge rst_n) begin
  if(!rst_n) begin
   col<=0;row<=0;fx1<=0;fy1<=0;fy2<=0;fy3<=0;fy4<=0;
   corrected<=0;
   for(c=0;c<3;c=c+1)begin
    {base0[c],base1[c],base02[c],base12[c],delta0[c],delta1[c],product0[c],product1[c],horizontal0[c],horizontal1[c],hbase4[c],vertical4[c],gain5[c],rgb_product[c]}<=0;
   end
   for(k=0;k<7;k=k+1) begin rq[k]<=0;tq[k]<=0;end
  end else begin
   if(timing_in[2]) begin col<=timing_in[0]?12'd0:x+1'b1;row<=timing_in[0]?y+1'b1:y;end
   rq[0]<=rgb_in;tq[0]<=timing_in;
   for(k=1;k<7;k=k+1) begin rq[k]<=rq[k-1];tq[k]<=tq[k-1];end
   // S1: nodes/differences. Signed extensions prevent negative wrap.
   fx1<=x[6:0];fy1<=y[6:0];fy2<=fy1;fy3<=fy2;fy4<=fy3;
   for(c=0;c<3;c=c+1)begin
    {base0[c],base1[c]}<={n00[(2-c)*10+:10],n01[(2-c)*10+:10]};
    {delta0[c],delta1[c]}<={($signed({1'b0,n10[(2-c)*10+:10]})-$signed({1'b0,n00[(2-c)*10+:10]})),
                           ($signed({1'b0,n11[(2-c)*10+:10]})-$signed({1'b0,n01[(2-c)*10+:10]}))};
    // S2/S3: horizontal interpolation with seven fractional bits.
    product0[c]<=delta0[c]*$signed({1'b0,fx1});product1[c]<=delta1[c]*$signed({1'b0,fx1});
    {base02[c],base12[c]}<={base0[c],base1[c]};
    {horizontal0[c],horizontal1[c]}<={($signed({2'd0,base02[c],7'd0})+product0[c]),($signed({2'd0,base12[c],7'd0})+product1[c])};
    // S4/S5: signed vertical delta and rounded Q8 gain, including G.
    vertical4[c]<=(horizontal1[c]-horizontal0[c])*$signed({1'b0,fy3});hbase4[c]<=horizontal0[c];
    gain5[c]<=(( $signed({{8{hbase4[c][18]}},hbase4[c]})<<<7)+vertical4[c]+27'sd8192)>>>14;
    rgb_product[c]<=rq[4][(2-c)*8+:8]*gain5[c];
   end
   // S6/S7: gain and saturation; bypass retains the identical delay.
   corrected<={clip(rgb_product[0]),clip(rgb_product[1]),clip(rgb_product[2])};
  end
 end
 assign timing_out=tq[6];assign input_aligned=rq[6];
 assign rgb_out=ENABLE!=0?corrected:rq[6];
endmodule
